package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class RootLifecycleSnapshotTest {
 static class Stored extends AbstractModule {int roles,enables,disables;Stored(String id){super(id,id,ModuleCategory.MISC);}public boolean ownsGameplayInput(){roles++;return true;}public boolean isPassiveObserver(){roles++;return false;}public void onEnable(){enables++;}public void onDisable(){disables++;}}
 @Test void snapshotUsesOnlyPrivateStoredFieldsWithoutRoleOrSupplierCallbacks(){var manager=new ModuleManager();var a=new Stored("a");manager.register(a);a.setEnabled(true);manager.leasedInputOwner(()->{fail("Supplier called");return a;});var s=manager.lifecycleSnapshot();assertTrue(s.known());assertTrue(manager.lifecycleCurrent(s));assertEquals(0,a.roles);assertEquals(1,a.enables);}
 @Test void lateCameraScanEnablesEarlierVisitedControllerAndInvalidatesSnapshot(){var manager=new ModuleManager();var a=new Stored("a");var b=new Stored("b");manager.register(b);manager.register(a);a.setEnabled(true);assertEquals(1,manager.enabledControllers().size());var before=manager.lifecycleSnapshot();java.util.function.Supplier<Object> camera=()->{b.setEnabled(true);return a;};assertSame(a,camera.get());assertFalse(manager.lifecycleCurrent(before));assertEquals(2,manager.enabledControllers().size());}
 @Test void directSetEnabledAbaIsDetectedWithoutChangingLifecycleCallbacks(){var manager=new ModuleManager();var a=new Stored("a");manager.register(a);a.setEnabled(true);var before=manager.lifecycleSnapshot();a.setEnabled(false);a.setEnabled(true);assertFalse(manager.lifecycleCurrent(before));assertEquals(2,a.enables);assertEquals(1,a.disables);}
 @Test void registrationAndInputBindingReplacementCannotPreserveOldProof(){var manager=new ModuleManager();var a=new Stored("a");manager.register(a);var s=manager.lifecycleSnapshot();manager.register(new Stored("b"));assertFalse(manager.lifecycleCurrent(s));s=manager.lifecycleSnapshot();manager.leasedInputOwner(()->a);assertFalse(manager.lifecycleCurrent(s));}
 @Test void equalEnabledWriteLeavesStoredVersionAndCallbacksUnchanged(){var manager=new ModuleManager();var a=new Stored("a");manager.register(a);a.setEnabled(true);var s=manager.lifecycleSnapshot();a.setEnabled(true);assertTrue(manager.lifecycleCurrent(s));assertEquals(1,a.enables);}
 @Test void unknownModuleImplementationDeniesScopedSnapshotWithoutCallingItsGetters(){var manager=new ModuleManager();Module unknown=new Module(){public String id(){return "unknown";}public String displayName(){return "unknown";}public ModuleCategory category(){return ModuleCategory.MISC;}public boolean isEnabled(){fail("Untrusted getter called");return false;}public void setEnabled(boolean enabled){}public void onEnable(){}public void onDisable(){}public void onTick(){}public MacroState state(){fail("Untrusted state called");return MacroState.STOPPED;}};manager.register(unknown);var s=manager.lifecycleSnapshot();assertFalse(s.known());assertFalse(manager.lifecycleCurrent(s));}
}
